window.GW_GHOST_PRE["gu"] = {"welcomeT":"GHOSTWALK માં આપનું સ્વાગત છે","welcomeV":"શું તમે આ સેવાનો ઉપયોગ કરતી વખતે અવાજ માર્ગદર્શન ઈચ્છો છો?","hear":"આ સંદેશ સાંભળો","whichLang":"તમારી પસંદગીની ભાષા પસંદ કરો.","moreLangs":"વધુ ભાષાઓ…","voiceQ":"શું તમે પણ અવાજ માર્ગદર્શન ઈચ્છો છો?","voiceOn":"વૉઇસ માર્ગદર્શન સક્ષમ કરો","voiceOff":"ફક્ત ટેક્સ્ટ સાથે ચાલુ રાખો","allSet":"બધા સેટ. હું અહીં ખૂણામાં રહીશ — જ્યારે પણ તમને મદદની જરૂર હોય ત્યારે મને ટેપ કરો.","close":"બંધ કરો","back":"← પાછળ","mute":"🔇 અવાજ મ્યૂટ કરો","unmute":"🔊 વૉઇસ બંધ — સક્ષમ કરવા માટે ટૅપ કરો","voiceNA":"આ ઉપકરણ પર આ ભાષા માટે વૉઇસ માર્ગદર્શન ઉપલબ્ધ નથી. ટેક્સ્ટ માર્ગદર્શન ચાલુ રહેશે.","pause":"⏸ થોભો","resume":"▶ ફરી શરૂ કરો","repeat":"🔁 પુનરાવર્તન કરો","disableV":"વૉઇસ અક્ષમ કરો","enableV":"વૉઇસ સક્ષમ કરો","changeL":"ભાષા બદલો","replay":"માર્ગદર્શનનું પુનરાવર્તન કરો","curL":"વર્તમાન ભાષા:","menuTitle":"હું કેવી રીતે મદદ કરી શકું?","tGuide":"આ પૃષ્ઠ દ્વારા મને માર્ગદર્શન આપો","tExplain":"આ વિકલ્પ સમજાવો","tRepeat":"છેલ્લી સૂચનાનું પુનરાવર્તન કરો","tVoiceOn":"અવાજ માર્ગદર્શન ચાલુ","tVoiceOff":"વૉઇસ માર્ગદર્શન બંધ","tMin":"નાનું કરો","tFull":"સંપૂર્ણ સહાયક ખોલો","tNext":"આગળ","tPrev":"પાછળ","tEnd":"અંત માર્ગદર્શિકા","tYes":"હા, મને માર્ગદર્શન આપો","tNotNow":"અત્યારે નહિ","guideOffer":"શું તમે આ વિકલ્પો માટે ઝડપી માર્ગદર્શિકા માંગો છો?","g_check":"શંકાસ્પદ સંદેશને અહીં પેસ્ટ કરો અથવા જો તમને તે સ્ક્રીનશોટ અથવા દસ્તાવેજ તરીકે પ્રાપ્ત થયો હોય તો અપલોડ વિકલ્પનો ઉપયોગ કરો. પાસવર્ડ, OTP અથવા બેંકિંગ ઓળખપત્રો શામેલ કરશો નહીં. એકવાર સામગ્રી તૈયાર થઈ જાય, નીચે વિશ્લેષણ બટન પસંદ કરો.","g_walk":"જો કોઈએ તમને શંકાસ્પદ રોકાણની લિંક મોકલી હોય, તો તેને ખોલ્યા વિના તેની નકલ કરો અને તેને આ બોક્સમાં પેસ્ટ કરો. જ્યારે તમે તૈયાર હોવ, ત્યારે \"તપાસ શરૂ કરો\" પસંદ કરો. GHOSTWALK ગંતવ્યને અલગથી તપાસવાનો પ્રયાસ કરશે અને તેણે જે વર્તન જોયું છે તે પરત કરશે.","g_qr":"સંપૂર્ણ QR કોડ ધરાવતો ફોટો અથવા સ્ક્રીનશૉટ પસંદ કરો. તમારે પેમેન્ટ એપ્લિકેશનનો ઉપયોગ કરીને તેને સ્કેન કરવાની જરૂર નથી. છબી પસંદ કર્યા પછી, પૂર્વાવલોકન તપાસો અને \"આ છબીનો ઉપયોગ કરો\" પસંદ કરો.","g_trusted":"પહેલા સારાંશની સમીક્ષા કરો. જો તે પરિસ્થિતિનું સચોટ વર્ણન કરે છે, તો તમે જે વિશ્વાસપાત્ર વ્યક્તિને સામેલ કરવા માંગો છો તેને પસંદ કરો. GHOSTWALK તેમના માટે ચેતવણીની માહિતી તૈયાર કરશે. મોકલતા પહેલા તેને તપાસો.","g_paid":"વધારાના પૈસા મોકલશો નહીં. શું અને ક્યારે ચૂકવવામાં આવ્યું હતું તે રેકોર્ડ કરીને પ્રારંભ કરો. પછી સ્ક્રીનશૉટ્સ, ચુકવણી સંદર્ભો અને સંદેશાઓ સાચવો. GHOSTWALK માહિતી ગોઠવશે અને આગળના સપોર્ટેડ પુનઃપ્રાપ્તિ પગલાં બતાવશે.","g_check_go":"ઉપરનો સંદેશ લખો અથવા પેસ્ટ કરો, પછી વિશ્લેષણ શરૂ કરવા માટે આ બટન દબાવો. ભૂત આ ઉપકરણ પર બધું વાંચે છે - કંઈપણ ખોલવામાં અથવા ચૂકવવામાં આવતું નથી.","g_walk_go":"લિંક નીચે ભૂત મોકલવા માટે આ બટન દબાવો. તે નકલી વિગતો સાથે મુસાફરીની સર્વર બાજુ પર ચાલે છે અને સુરક્ષિત રીતે અટકી જાય છે — તમે તેને ક્યારેય જાતે ખોલતા નથી.","g_qr_go":"UPI વિગતો પેસ્ટ કર્યા પછી આ બટન દબાવો. ભૂત ડીકોડ કરે છે કે પૈસા ક્યાં જશે અને ચૂકવનારને, રકમ અને ચેતવણીઓ બતાવે છે.","g_trusted_go":"ચેતવણી તૈયાર કરવા માટે આ બટન દબાવો. તમારા વિશ્વસનીય વ્યક્તિ સાથે શેર કરતા પહેલા પૂર્વાવલોકન કાળજીપૂર્વક વાંચો.","g_paid_go":"તમારું ઘટના પેક બનાવવા માટે આ બટન દબાવો. તે 1930 હેલ્પલાઈન માટે તમારી સમયરેખા અને પુરાવાઓને ગોઠવે છે — પુનઃપ્રાપ્તિની ક્યારેય ખાતરી આપવામાં આવતી નથી.","m_start":"હવે ગંતવ્યની તપાસ એક અલગ વાતાવરણમાં કરવામાં આવી રહી છે.","m_done":"તપાસ પૂર્ણ થઈ ગઈ છે. હું એક પછી એક તારણો સમજાવી શકું છું.","langChanged":"ભાષા બદલાઈ. હું તમને આ ભાષામાં માર્ગદર્શન આપવાનું ચાલુ રાખીશ.","voiceWelcome":"ઘોસ્ટવોકમાં આપનું સ્વાગત છે. હું તમને માર્ગદર્શન આપવા અહીં છું. હું દરેક વિકલ્પ સમજાવી શકું છું અને આગળ શું કરવું તે તમને બતાવી શકું છું.","textWelcome":"GHOSTWALK માં આપનું સ્વાગત છે. જો તમને મદદની જરૂર હોય તો હું અહીં છું. નાના ભૂતને ટેપ કરો કે કોઈ? સમજૂતી માટે ચિહ્ન.","hintHome":"મદદની જરૂર છે? ટેપ કરો? કોઈપણ વિકલ્પની બાજુમાં, અથવા માર્ગદર્શિત પ્રવાસ માટે ઘોસ્ટ ખોલો.","tExplainChoice":"તમે મને શું સમજાવવા માંગો છો?","explainName_checkMessage":"એક સંદેશ તપાસો","explainName_walkLink":"એક લિંક ચાલો","explainName_qr":"QR/UPI ડીકોડ કરો","explainName_trustedContact":"હું વિશ્વાસુ કોઈને ચેતવણી આપો","explainName_alreadyPaid":"મેં પહેલેથી જ ચૂકવણી કરી છે","vLead":"અહીં શા માટે છે, સરળ શબ્દોમાં.","vReason":"કારણ {n}:","vExample":"ઉદાહરણ તરીકે:","vRephrase":"બીજા શબ્દોમાં કહીએ તો,","vDoubt":"જ્યારે શંકા હોય, ત્યારે હજુ સુધી ચૂકવણી કરશો નહીં. પ્રથમ તમે વિશ્વાસુ વ્યક્તિ સાથે વાત કરો.","emptyRead":"હજી કંઈ વાંચવાનું નથી.","translating":"પૃષ્ઠનો અનુવાદ કરી રહ્યાં છીએ — એક ક્ષણ…","netStruggle":"અનુવાદ આ નેટવર્ક પર સંઘર્ષ કરી રહ્યો છે — હમણાં માટે અંગ્રેજી બતાવી રહ્યું છે.","qrUpload":"QR છબી અપલોડ કરો","qrUploadSub":"QR કોડ ધરાવતો ફોટો અથવા સ્ક્રીનશૉટ અપલોડ કરો. GHOSTWALK ચુકવણી શરૂ કર્યા વિના તેને ડીકોડ કરશે.","qrDrop":"…અથવા અહીં એક છબી ખેંચો અને છોડો","qrTakePhoto":"ફોટો લો","qrUse":"આ છબીનો ઉપયોગ કરો","qrChange":"બીજું પસંદ કરો","qrRemove":"દૂર કરો","qrNoCode":"અમે આ છબીમાંથી QR કોડ વાંચી શક્યા નથી. જ્યાં આખો QR કોડ દેખાતો હોય ત્યાં સ્પષ્ટ છબી અજમાવો.","qrTooBig":"તે છબી ખૂબ મોટી છે. કૃપા કરીને 8 MB હેઠળની છબી પસંદ કરો.","qrBadFile":"તે ફાઇલ છબી તરીકે વાંચી શકાતી નથી. કૃપા કરીને PNG, JPG અથવા WebP સ્ક્રીનશૉટ પસંદ કરો.","qrType":"પ્રકાર","qrUpi":"UPI ચુકવણી વિનંતી","qrUrl":"વેબ લિંક","qrText":"ટેક્સ્ટ","qrPayee":"લેનાર / UPI ID","qrName":"નામ","qrAmount":"રકમ","qrNote":"નોંધ / સંદર્ભ","qrDecodeUpi":"ડીકોડ ચુકવણી હેતુ","qrInvestigate":"આ લિંકની સલામત રીતે તપાસ કરો","qrFoundTitle":"QR મળ્યો","qrGuideSteps":"નમૂના QR છબી લોડ કરવામાં આવી છે. છબી પૂર્વાવલોકન સમીક્ષા કરો. આ છબીનો ઉપયોગ કરો પસંદ કરો. GHOSTWALK હવે તેના સમાવિષ્ટોને ડીકોડ કરશે.","g_qr_img":"જો કોઈએ તમને રોકાણ અથવા ચુકવણી માટે QR કોડ મોકલ્યો હોય, તો અહીં ચિત્ર અપલોડ કરો. તમારે તમારી ચુકવણી એપ્લિકેશનનો ઉપયોગ કરીને તેને સ્કેન કરવાની જરૂર નથી માત્ર તે જોવા માટે કે તેમાં શું છે. ડીકોડિંગ પછી, બીજું કંઈપણ કરતા પહેલા ગંતવ્યની સમીક્ષા કરો.","g_qr_found":"QR સમાવે છે તે અહીં છે. કંઈ ચૂકવવામાં આવ્યું ન હતું અને કંઈપણ ખોલવામાં આવ્યું ન હતું.","sampleNote":"નમૂના - માત્ર પ્રદર્શન માટે.","sampleJourneyNote":"નિયંત્રિત પ્રદર્શન પ્રવાસ — સલામત પરીક્ષણ ગંતવ્ય, જીવંત ખતરો નહીં.","sampleQrNote":"નમૂના QR — માત્ર પ્રદર્શન. કોઈ ચુકવણી શરૂ કરવામાં આવી નથી.","sampleCaseNote":"નમૂના પુનઃપ્રાપ્તિ કેસ — કાલ્પનિક ડેમો ડેટા. પુનઃપ્રાપ્તિ ક્યારેય ગેરંટી નથી.","sampleAlertText":"મને એક રોકાણ વિનંતી પ્રાપ્ત થઈ છે જે GHOSTWALK ને વધુ ચકાસણીની આવશ્યકતા તરીકે ઓળખવામાં આવી છે. હું આગળ વધતા પહેલા, શું તમે મારી સાથે આની સમીક્ષા કરી શકશો?","sampleContact":"નમૂના સંપર્ક","packNeed":"પહેલા જે બન્યું તેમાં ઓછામાં ઓછું એક પગલું ઉમેરો.","carriedOver":"👻 તમારા પૃથ્થકરણમાંથી વહન કર્યું — સમીક્ષા કરો અને ડ્રાફ્ટ દબાવો.","explain":"સમજાવો","readAloud":"મોટેથી વાંચો","notNow":"અત્યારે નહિ","resultsReady":"તમારું પરિણામ નીચે તૈયાર છે. મને ટેપ કરો અને હું તેને સરળ રીતે સમજાવીશ.","uncertain":"અમે આને વિશ્વસનીય રીતે ચકાસી શક્યાં નથી. તેનો અર્થ એ નથી કે તે સુરક્ષિત છે. કૃપા કરીને જ્યાં સુધી તમે તેને સ્વતંત્ર રીતે ચકાસશો નહીં ત્યાં સુધી આગળ વધશો નહીં.","checking":"ચેક નીચે ચાલી રહ્યો છે. તે ગંતવ્યને એકાંતમાં વાંચે છે, તેથી તમારે જાતે કંઈપણ સ્પર્શ કરવાની જરૂર નથી.","understood":"સમજાયું. જો તમને મારી જરૂર હોય તો હું અહીં છું.","noResult":"પહેલા ચેક ચલાવો — પછી હું તે બરાબર શું મળ્યું તે સમજાવી શકું.","m_index_t":"GHOSTWALK શું કરે છે","m_index":["તમને જે મળ્યું છે તે પસંદ કરો: સંદેશ, લિંક, QR, વિશ્વસનીય વ્યક્તિ અથવા પહેલેથી ચૂકવેલ સહાય.","તમે ક્યારેય શંકાસ્પદ લિંક્સ જાતે ખોલતા નથી - ભૂત તેમને સર્વર-સાઇડ લઈ જાય છે.","તમે માત્ર ક્યારેય સ્ટોપ મેળવો છો અથવા ચકાસાયેલ નથી. ક્યારેય ખોટું “સુરક્ષિત” નહીં."],"m_message_t":"સંદેશ તપાસી રહ્યા છીએ","m_message":["ટેક્સ્ટ ટેબમાં ચેટ પેસ્ટ કરો અને વિશ્લેષણ દબાવો.","ફોટો ટેબ સ્ક્રીનશોટ વાંચે છે અને છુપાયેલા QR કોડ્સ શોધે છે.","પીડીએફ ટેબ બ્રોશર વાંચે છે. વૉઇસ ટેબ તમને ટાઇપ કરવાને બદલે બોલવા દે છે."],"m_ghost_t":"એક લિંક વૉકિંગ","m_ghost":["બોક્સમાં શંકાસ્પદ લિંક પેસ્ટ કરો. તેને જાતે ખોલશો નહીં.","\"ભૂત મોકલો\" દબાવો અને નીચેનો રિપ્લે જુઓ.","ભૂત માત્ર નકલી વિગતોનો ઉપયોગ કરે છે - તમારી ક્યારેય નહીં."],"m_qr_t":"QR/UPI વાંચવું","m_qr":["QR પાછળ છુપાયેલ UPI સ્ટ્રિંગ પેસ્ટ કરો — તેને ક્યારેય જાતે સ્કેન કરશો નહીં.","ભૂત વાંચે છે કે પૈસા ખરેખર ક્યાં જશે.","બતાવેલ નામની વાસ્તવિક કંપની સાથે અલગથી સરખામણી કરો."],"m_trusted_t":"તમે વિશ્વાસુ વ્યક્તિને પૂછો","m_trusted":["નામ અને રકમ ભરો, પછી ડ્રાફ્ટ દબાવો.","તમારા પરિવાર સાથે WhatsApp પર ટૂંકો સંદેશ શેર કરો.","તેઓ કંઈપણ મંજૂર કરતા નથી - તેઓ ફક્ત તમારી સાથે ઉભા છે."],"m_recovery_t":"જો તમે પહેલેથી જ ચૂકવણી કરી છે","m_recovery":["પગલું દ્વારા પગલું ઉમેરો.","\"મારું ઘટના પેક બનાવો\" દબાવો અને તેને ડાઉનલોડ કરો.","તેને તમારી બેંક અને હેલ્પલાઇન 1930 પર લઈ જાઓ. આગળની બધી ચૂકવણીઓ રોકો."],"understand":"મારું પરિણામ સમજો","saidRed":"આ STOP કહે છે. ચૂકવણી કરશો નહીં અને OTP અથવા બેંક વિગતો શેર કરશો નહીં.","qrFoundSay":"QR મળ્યો. {detail}","saidYellow":"આ NOT VERIFIED કહે છે. હજુ ચુકવણી કરશો નહીં."};
